def min_absolute_difference(nums: List[int], k: int) -> int:
    """Minimize |k - OR(subarray)| over all non-empty contiguous subarrays."""
    best = float("inf")
    previous = []
    for value in nums:
        current = [value]
        for old_or in previous:
            combined = old_or | value
            if combined != current[-1]:
                current.append(combined)
        for subarray_or in current:
            best = min(best, abs(k - subarray_or))
            if best == 0:
                return 0
        previous = current
    return int(best)
